<script setup lang="ts">
import {ref,onMounted,onBeforeUnmount} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {api,errorText,type Store} from './api'
interface Task {task_id:string;store_id:number;status:string;user_query:string;created_at:string;intent:string|null;selected_agents:string[];error_code:string|null;error_summary:string|null;report_json:Record<string,string|string[]>|null;trace_json:{route:{intent:string;reason:string}|null;tools:{node:string;tool:string;status:string;started_at:string;ended_at:string;error:string|null;summary:string}[]}}
const route=useRoute(),router=useRouter();const stores=ref<Store[]>([]),store=ref<number>();const dates=ref<[string,string]>(['2026-01-01','2026-03-31']);const sku=ref(''),query=ref(''),submitting=ref(false),error=ref(''),task=ref<Task>(),history=ref<Task[]>([]);const page=ref(1),total=ref(0);let timer:ReturnType<typeof setTimeout>|undefined;let disposed=false;let request=0;let listRequest=0
const labels:Record<string,string>={queued:'等待执行',running:'分析中',completed:'已完成',partial_failed:'部分失败',failed:'失败',unsupported:'不支持的问题',interrupted:'已中断'}
const sections:Record<string,string>={problem_understanding:'问题理解',key_findings:'关键发现',business_risks:'经营风险',suggested_actions:'建议措施（尚未执行）',evidence_and_limits:'数据依据与限制',evidence_ids:'证据引用'}
const active=()=>task.value && ['queued','running'].includes(task.value.status)
function stop(){clearTimeout(timer)}
async function list(){if(!store.value)return;const own=++listRequest;try{const r=await api.get('/agent/tasks',{params:{store_id:store.value,page:page.value,page_size:10}});if(!disposed&&own===listRequest){history.value=r.data.items;total.value=r.data.total}}catch(e){if(!disposed)error.value=errorText(e)}}
async function detail(id:string){stop();const own=++request;try{const r=await api.get<Task>('/agent/tasks/'+encodeURIComponent(id));if(disposed||own!==request)return;task.value=r.data;error.value='';if(active())timer=setTimeout(()=>detail(id),2000);else await list()}catch(e){if(!disposed&&own===request)error.value=errorText(e)}}
async function open(id:string){await router.replace({query:{task_id:id}});await detail(id)}
async function submit(){if(submitting.value||active()||!store.value||!dates.value?.[0]||!dates.value?.[1]||!query.value.trim())return;submitting.value=true;error.value='';try{const r=await api.post('/agent/tasks',{store_id:store.value,user_query:query.value.trim(),start_date:dates.value[0],end_date:dates.value[1],selected_sku:sku.value.trim()||null});await open(r.data.task_id);await list()}catch(e){error.value=errorText(e)}finally{submitting.value=false}}
async function changeStore(){page.value=1;await list()}
onMounted(async()=>{try{stores.value=(await api.get<Store[]>('/stores')).data;if(disposed)return;store.value=stores.value[0]?.id;await list();if(typeof route.query.task_id==='string')await detail(route.query.task_id)}catch(e){error.value=errorText(e)}})
onBeforeUnmount(()=>{disposed=true;request++;stop()})
</script>
<template><section><div class="eyebrow">AI ANALYSIS WORKSPACE</div><h1>AI 任务中心</h1><p>提交经营问题，查看可追溯的分析报告。仅限本地可信演示环境，无用户授权系统。</p><el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/><div class="panel"><div class="filters" style="margin:0"><el-select v-model="store" placeholder="店铺" style="width:220px" @change="changeStore"><el-option v-for="s in stores" :key="s.id" :label="s.name" :value="s.id"/></el-select><el-date-picker v-model="dates" type="daterange" value-format="YYYY-MM-DD" start-placeholder="开始日期" end-placeholder="结束日期"/><el-input v-model="sku" placeholder="SKU 可选，例如 DEMO-001" style="width:240px"/></div><el-input v-model="query" type="textarea" :rows="4" maxlength="4000" show-word-limit placeholder="例如：分析 DEMO-001 的利润和广告表现" style="margin:18px 0"/><div class="alerts"><button v-for="example in ['分析贡献利润与经营风险','分析广告效率与高 ACOS 商品','检查断货与滞销库存']" :key="example" @click="query=example">{{example}}</button></div><el-button type="primary" style="margin-top:18px" :loading="submitting" :disabled="!query.trim()||!store||!!active()" @click="submit">{{active()?'当前任务执行中':'创建分析任务'}}</el-button></div><div v-if="task" class="panel"><h2>任务结果 <el-tag :type="task.status==='completed'?'success':['failed','partial_failed','interrupted'].includes(task.status)?'danger':'info'">{{labels[task.status]||task.status}}</el-tag></h2><p style="overflow-wrap:anywhere">任务 ID：{{task.task_id}}</p><p>{{task.user_query}}</p><p v-if="active()">正在后台分析，每两秒更新状态；请勿重复提交。耗时取决于模型服务，未提供虚构进度。</p><el-alert v-if="task.error_code" :title="(task.error_summary||'任务异常')+' ['+task.error_code+']'" type="warning" :closable="false"/><div v-if="task.report_json"><article v-for="(title,key) in sections" :key="key" class="report-section"><h3>{{title}}</h3><ul v-if="Array.isArray(task.report_json[key])"><li v-for="(text,i) in task.report_json[key]" :key="i">{{text}}</li></ul><p v-else>{{task.report_json[key]}}</p></article></div><h3>Supervisor 路由与执行轨迹</h3><p>意图：{{task.intent||'尚未完成'}} · Agent：{{task.selected_agents.join('、')||'—'}}</p><p v-if="task.trace_json.route">路由说明：{{task.trace_json.route.reason}}</p><el-table :data="task.trace_json.tools" empty-text="尚无已保存的工具轨迹"><el-table-column prop="node" label="节点" min-width="150"/><el-table-column prop="tool" label="工具" min-width="170"/><el-table-column prop="status" label="状态"/><el-table-column prop="started_at" label="开始（UTC）" min-width="210"/><el-table-column prop="ended_at" label="结束（UTC）" min-width="210"/><el-table-column prop="error" label="错误" min-width="150"/></el-table></div><div class="panel"><h2>历史任务</h2><el-button @click="list">刷新历史</el-button><el-table :data="history" empty-text="当前店铺尚无分析任务" @row-click="(row:Task)=>open(row.task_id)"><el-table-column prop="user_query" label="问题" min-width="230"/><el-table-column label="状态" width="120"><template #default="{row}">{{labels[row.status]}}</template></el-table-column><el-table-column prop="created_at" label="创建（UTC）" min-width="200"/><el-table-column prop="task_id" label="任务 ID（点击查看）" min-width="300"/></el-table><el-pagination v-model:current-page="page" :page-size="10" :total="total" layout="prev,pager,next" @current-change="list"/></div></section></template>
<style scoped>.report-section{border-top:1px solid #eef0f4;padding:10px 0;overflow-wrap:anywhere}.report-section li{font-size:14px;line-height:1.9;color:#566177}h3{font-size:15px}.el-pagination{margin-top:16px}</style>
